Lemma brk_req_sound : forall E cs R FULL model d,
  cs_ok E cs R FULL model -> brk_req cs = Some d ->
  0 < d /\ d mod 4096 = 0 /\ d <= 2 ^ 40 /\
  (bv_unsigned (edenot E (reg cs 10)) - bv_unsigned (vm_brk (m_vmmaps model))) mod two64 = d.
