  cs_ok E cs R FULL model -> brk_req cs = Some d -> brk_base_ok A cs d = true ->
  getr R (Z_to_bv 5 (Z.of_nat 10)) = Z_to_bv 64 (bv_unsigned (vm_brk (m_vmmaps model)) + d).
