         let '(v, xm') := in_sidesM bc xm (sp_D sp) b1 k1 n1 in
         if v then (true, xm') else (lin_apartB bc b1 k1 n1 b2 k2 n2, xm')
       else ((if kdisj_apartB bc kd b1 k1 n1 b2 k2 n2 then true else lin_apartB bc b1 k1 n1 b2 k2 n2), xm).
