Lemma ivof_spec : forall k w s e, ivof k w = Some (s, e) ->
  Uint63.to_Z s = k + 2 ^ 61 /\ Uint63.to_Z e = k + w + 2 ^ 61 /\ - 2 ^ 60 < k < 2 ^ 60 /\ 0 <= w < 2 ^ 61.
Proof.
